sys_script_include.script:
var VehicleUtilsAjax = Class.create();
VehicleUtilsAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getVehicleDetails: function() {
        var id = this.getParameter('sysparm_vehicle');
        var gr = new GlideRecord('x_2220337_vehicl_0_vehicle');

        if (!gr.get(id)) return '';

        return JSON.stringify({
            ownerId: gr.getValue('owner'),
            ownerName: gr.owner.getDisplayValue(),
            model: gr.getValue('make') + ' ' + gr.getValue('model'),
            lastService: gr.getDisplayValue('last_service_date') || 'Never',
            premium: gr.owner.customer_type == 'premium'
        });
    },

    type: 'VehicleUtilsAjax'
});
